using System;using System.IO;using Serilog;namespace SAUDICO.Federate.Logging;public static class LoggingBootstrapper { public static void Start(){var dir=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),"SAUDICO","Federate","logs");Directory.CreateDirectory(dir);Log.Logger=new LoggerConfiguration().MinimumLevel.Information().WriteTo.File(Path.Combine(dir,"federate-.log"),rollingInterval:RollingInterval.Day,retainedFileCountLimit:30).CreateLogger();}public static void Stop()=>Log.CloseAndFlush(); }
